// Let's inspect the page content to find items, prices, and Amazon purchase links
const items = await browserjs(nytTabId, () => {
  // Let's see how Wirecutter structures gift items
  const results = [];

  // Wirecutter often uses h3 or h2 for items, or product cards
  const headings = Array.from(document.querySelectorAll('h2, h3, h4'));
  for (const h of headings) {
    const text = h.innerText.trim();
    if (!text) continue;
    // Find parent container or following siblings
    let container = h.closest('[data-gtm-trigger="product_card"]') || h.closest('article') || h.parentElement;
    // Look for buy links in or near container
    const links = Array.from(container ? container.querySelectorAll('a') : []).map(a => ({
      text: a.innerText.trim(),
      href: a.href
    })).filter(l => l.href.includes('amazon.com') || l.text.toLowerCase().includes('amazon') || l.text.toLowerCase().includes('$'));

    // Also look for price in text
    results.push({
      heading: text,
      links: links.slice(0, 5)
    });
  }
  return results.filter(r => r.links.length > 0).slice(0, 15);
});

console.log("Found items:", JSON.stringify(items, null, 2));

const nytTabId = 103795319;

// Let's inspect the actual product cards and their buying options
const productCards = await browserjs(nytTabId, () => {
  // Let's find elements that contain product recommendations
  // Wirecutter typically wraps product recommendations in sections or divs with headings
  const cards = [];

  // Look for elements with class or data attributes, or query all h3 elements
  const h3s = Array.from(document.querySelectorAll('h3'));
  for (const h3 of h3s) {
    const title = h3.innerText.trim();
    // Let's see the section/container around this h3
    let parent = h3.parentElement;
    let cardEl = null;
    while (parent && parent !== document.body) {
      if (parent.querySelector('a[data-gtm-trigger="buy_button"]') || parent.innerText.includes('Buying options:')) {
        cardEl = parent;
        break;
      }
      parent = parent.parentElement;
    }

    if (cardEl) {
      // Find buy links specifically inside this cardEl
      const buyLinks = Array.from(cardEl.querySelectorAll('a'))
        .filter(a => a.innerText.includes('Amazon') || a.href.includes('amazon') || a.href.includes('merchant=Amazon'))
        .map(a => ({
          text: a.innerText.trim().replace(/\n+/g, ' '),
          href: a.href
        }));

      // Get price text
      const priceText = cardEl.innerText.match(/\$\d+(\.\d+)?/)?.[0] || '';

      cards.push({
        title,
        priceText,
        buyLinks
      });
    }
  }
  return cards;
});

