const items = await browserjs(nytTabId, () => {
  // Let's see how Wirecutter structures gift items
  const results = [];

  // Wirecutter often uses h3 or h2 for items, or product cards
  const headings = Array.from(document.querySelectorAll('h2, h3, h4'));
  for (const h of headings) {
    const text = h.innerText.trim();
    if (!text) continue;
    // Find parent container or following siblings
    let container = h.closest('[data-gtm-trigger="product_card"]') || h.closest('article') || h.parentElement;
    // Look for buy links in or near container
    const links = Array.from(container ? container.querySelectorAll('a') : []).map(a => ({
      text: a.innerText.trim(),
      href: a.href
    })).filter(l => l.href.includes('amazon.com') || l.text.toLowerCase().includes('amazon') || l.text.toLowerCase().includes('$'));

    // Also look for price in text
    results.push({
      heading: text,
      links: links.slice(0, 5)
    });
  }
  return results.filter(r => r.links.length > 0).slice(0, 15);
});

