const nytTabId = 103795319;

// Let's inspect the actual product cards and their buying options
const productCards = await browserjs(nytTabId, () => {
  // Let's find elements that contain product recommendations
  // Wirecutter typically wraps product recommendations in sections or divs with headings
  const cards = [];

  // Look for elements with class or data attributes, or query all h3 elements
  const h3s = Array.from(document.querySelectorAll('h3'));
  for (const h3 of h3s) {
    const title = h3.innerText.trim();
    // Let's see the section/container around this h3
    let parent = h3.parentElement;
    let cardEl = null;
    while (parent && parent !== document.body) {
      if (parent.querySelector('a[data-gtm-trigger="buy_button"]') || parent.innerText.includes('Buying options:')) {
        cardEl = parent;
        break;
      }
      parent = parent.parentElement;
    }

    if (cardEl) {
      // Find buy links specifically inside this cardEl
      const buyLinks = Array.from(cardEl.querySelectorAll('a'))
        .filter(a => a.innerText.includes('Amazon') || a.href.includes('amazon') || a.href.includes('merchant=Amazon'))
        .map(a => ({
          text: a.innerText.trim().replace(/\n+/g, ' '),
          href: a.href
        }));

      // Get price text
      const priceText = cardEl.innerText.match(/\$\d+(\.\d+)?/)?.[0] || '';

      cards.push({
        title,
        priceText,
        buyLinks
      });
    }
  }
  return cards;
});

console.log("Product cards found:", JSON.stringify(productCards.filter(c => c.buyLinks.length > 0).slice(0, 10), null, 2));

