  action: "down",
  tabId: searchTabId,
  coordinate: [415, 510]
});

// Perform realistic moves from 415 to 588 in 15 steps with easing and slight jitter
const startX = 415;
const endX = 588;
const y = 510;
const steps = 18;

for (let i = 1; i <= steps; i++) {
  // Easing function (easeOutQuad or smoothstep)
  const t = i / steps;
  // smoothstep: 3*t^2 - 2*t^3
  const progress = t * t * (3 - 2 * t);
  const curX = Math.round(startX + (endX - startX) * progress);
  const jitterY = y + (Math.sin(i * 0.8) * 2);

  await tool.mouse({
    action: "move",
    tabId: searchTabId,
    coordinate: [curX, Math.round(jitterY)]
  });
}

// Mouse up at end coordinate
await tool.mouse({
  action: "up",
  tabId: searchTabId,
  coordinate: [endX, y]
});

// Wait for verification
