const tabId = 103795220;

// Inspect the Holiday Collection products
const products = await browserjs(tabId, () => {
  const items = [];
  // Find product elements
  const links = Array.from(document.querySelectorAll('a[href*="/products/"]'));
  const seen = new Set();

  for (const a of links) {
    const cleanUrl = a.href.split('?')[0];
    if (seen.has(cleanUrl)) continue;

    // Find parent container
    let container = a.closest('.product-card') || a.closest('.grid__item') || a.parentElement;
    let title = a.innerText.trim() || container?.querySelector('h3, .product-card__title, .card__heading')?.innerText.trim() || '';
    let price = container?.querySelector('.price, .price-item, .money')?.innerText.trim() || '';

    // If title has newlines or is empty, clean it up
    if (title) {
      title = title.split('\n')[0].trim();
      seen.add(cleanUrl);
      items.push({ title, price, url: cleanUrl });
    }
  }
  return items;
});

console.log("Holiday Collection products:", JSON.stringify(products, null, 2));

