// Find another Etsy listing URL on DDG
const tabId = 103795220;
const queryUrl = "https://html.duckduckgo.com/html/?q=" + encodeURIComponent('site:etsy.com/listing "custom christmas ornament"');
await tool.navigate({ tabId, url: queryUrl });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const listings = await browserjs(tabId, () => {
  const items = [];
  const results = document.querySelectorAll('.result');
  for (const r of results) {
    const a = r.querySelector('.result__url, .result__title a');
    const title = r.querySelector('.result__title')?.innerText.trim();
    const url = a?.href || '';
    if (url.includes('etsy.com/listing') || r.innerText.includes('etsy.com/listing')) {
      items.push({ title, url: r.querySelector('.result__url')?.innerText.trim() });
    }
  }
  return items;
});

console.log("Found Etsy listings:", JSON.stringify(listings, null, 2));

